<div class="modal fade" id="pentaxManageModal" tabindex="-1" role="dialog" aria-labelledby="pentaxManageTitle" aria-hidden="true"><div class="modal-dialog px-modal-dialog" role="document"><div class="modal-content px-modal-shell"><div class="px-modal-loading"><i class="fas fa-circle-notch fa-spin"></i><strong>Cargando gestión del procedimiento…</strong></div></div></div></div>
<script>
(function($){'use strict';
  window.initPentaxSubinsurance=function(scope){var root=$(scope||document),insurance=root.find('.js-pentax-insurance').first(),sub=root.find('.js-pentax-subinsurance').first(),help=root.find('.js-pentax-subinsurance-help').first();if(!insurance.length||!sub.length)return;function filter(){var insuranceId=String(insurance.val()||''),current=String(sub.val()||''),visible=0;sub.find('option[data-insurance]').each(function(){var match=String($(this).data('insurance'))===insuranceId;$(this).prop({'disabled':!match,'hidden':!match}).toggle(match);if(match)visible++;});if(current&&sub.find('option[value="'+current+'"]:not(:disabled)').length===0)sub.val('');sub.prop('disabled',visible===0);help.text(visible?visible+' subseguro(s) disponible(s) para el convenio seleccionado.':'Este convenio no tiene subseguros activos.');}insurance.off('change.pentaxSubinsurance').on('change.pentaxSubinsurance',filter);filter();};
  window.initPentaxProcedurePicker=function(scope){var root=$(scope||document),picker=root.find('.js-pentax-procedures').first(),help=root.find('.js-pentax-procedure-help').first();if(!picker.length)return;function updateCount(){var count=(picker.val()||[]).length;help.text(count?(count===1?'1 procedimiento seleccionado.':count+' procedimientos seleccionados.')+' Puedes buscar y agregar más.':'Busca por nombre y selecciona uno o varios procedimientos.');}if($.fn.select2){picker.select2({theme:'bootstrap4',width:'100%',closeOnSelect:false,placeholder:picker.data('placeholder'),dropdownParent:picker.closest('.modal').length?picker.closest('.modal'):$(document.body),language:{noResults:function(){return 'No se encontraron procedimientos';},searching:function(){return 'Buscando…';}}});picker.off('change.pentaxProcedures').on('change.pentaxProcedures',updateCount);}updateCount();};
  function showPentaxAlert(options){if(typeof window.mostrarSweetAlertV3==='function')return window.mostrarSweetAlertV3(options);if(window.Swal&&typeof window.Swal.fire==='function')return window.Swal.fire(options);return Promise.reject();}
  $(document).on('submit','.js-pentax-room-form',function(event){event.preventDefault();});
  $(document).on('change','.js-pentax-room',function(){var select=$(this),form=select.closest('form'),state=form.find('.px-room-state'),previous=String(select.data('savedValue')||''),selected=String(select.val()||''),formData=form.serialize();if(selected===previous)return;select.prop('disabled',true);state.removeClass('is-success is-error').addClass('is-saving').html('<i class="fas fa-circle-notch fa-spin" title="Guardando sala"></i>');$.ajax({url:form.attr('action'),type:'POST',data:formData,headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}}).done(function(response){select.data('savedValue',selected);state.removeClass('is-saving is-error').addClass('is-success').html('<i class="fas fa-check" title="Sala guardada"></i>');showPentaxAlert({toast:true,position:'top-end',icon:'success',title:response.message||'Sala actualizada',showConfirmButton:false,timer:1800,timerProgressBar:true}).catch(function(){});window.setTimeout(function(){if(String(select.data('savedValue'))===selected)state.empty().removeClass('is-success');},2200);}).fail(function(xhr){select.val(previous);state.removeClass('is-saving is-success').addClass('is-error').html('<i class="fas fa-exclamation-circle" title="No se guardó la sala"></i>');var response=xhr.responseJSON||{},message=response.message||'No fue posible actualizar la sala.';showPentaxAlert({icon:'error',title:'No se pudo cambiar la sala',text:message,confirmButtonText:'Entendido',confirmButtonColor:'#087eae'}).catch(function(){});}).always(function(){select.prop('disabled',false);});});
  $(document).on('click','.js-pentax-manage',function(event){event.preventDefault();var modal=$('#pentaxManageModal'),shell=modal.find('.px-modal-shell'),oldPicker=shell.find('.js-pentax-procedures');if(oldPicker.length&&oldPicker.data('select2'))oldPicker.select2('destroy');shell.html('<div class="px-modal-loading"><i class="fas fa-circle-notch fa-spin"></i><strong>Cargando gestión del procedimiento…</strong></div>');modal.modal('show');$.ajax({url:this.href,type:'GET',headers:{'X-Requested-With':'XMLHttpRequest'}}).done(function(html){shell.html(html);window.initPentaxSubinsurance(shell);window.initPentaxProcedurePicker(shell);}).fail(function(xhr){var message=xhr.responseJSON&&xhr.responseJSON.message?xhr.responseJSON.message:'No se pudo cargar la gestión del procedimiento.';shell.html('<div class="px-modal-error"><i class="fas fa-exclamation-circle"></i><strong>'+ $('<div>').text(message).html() +'</strong><button type="button" class="btn btn-outline-secondary" data-dismiss="modal">Cerrar</button></div>');});});
  $(document).on('submit','.js-pentax-update-form',function(event){event.preventDefault();var form=$(this),button=form.find('.js-pentax-save'),errors=form.closest('.px-editor-card').find('.px-form-errors');errors.empty().hide();button.prop('disabled',true).html('<i class="fas fa-circle-notch fa-spin mr-1"></i> Guardando…');$.ajax({url:form.attr('action'),type:'POST',data:form.serialize(),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}}).done(function(response){var redirect=function(){window.location.href=response.redirect;};showPentaxAlert({icon:'success',title:'Procedimiento actualizado',text:response.message||'Los cambios se guardaron correctamente.',confirmButtonText:'Aceptar',confirmButtonColor:'#087eae',timer:1800,timerProgressBar:true}).then(redirect).catch(redirect);}).fail(function(xhr){var payload=xhr.responseJSON||{},messages=[],source=payload.errors||payload,keys=Object.keys(source),firstField='';keys.forEach(function(key){if(key==='message'&&payload.errors)return;if(!firstField&&key!=='message')firstField=key.split('.')[0];var value=source[key];if(Array.isArray(value))messages=messages.concat(value);else if(typeof value==='string')messages.push(value);});if(!messages.length)messages.push(payload.message||'No fue posible guardar los cambios.');button.prop('disabled',false).html('<i class="fas fa-save mr-1"></i> Guardar y registrar en log');var escaped=messages.map(function(message){return '<div>'+ $('<div>').text(message).html() +'</div>';}).join('');showPentaxAlert({icon:'warning',title:'Revise la información',html:escaped,confirmButtonText:'Corregir',confirmButtonColor:'#087eae',allowOutsideClick:false}).then(function(){var field=form.find('[name="'+firstField+'"],[name="'+firstField+'[]"]').first();if(firstField==='proc'&&field.data('select2'))field.select2('open');else if(field.length)field.trigger('focus');}).catch(function(){errors.html('<div class="alert alert-danger px-alert">'+escaped+'</div>').show();});});});
})(jQuery);
</script>
